# Selective Server-Side Rendering (SSR)
## Configuration [#](https://tanstack.com/start/v0/docs/framework/react/guide/selective-ssr#configuration)
```
// src/start.ts
import { createStart } from '@tanstack/react-start'

export const startInstance = createStart(() => ({
  // Disable SSR by default
  defaultSsr: false,
}))
```

## How to disable SSR of the root route? [#](https://tanstack.com/start/v0/docs/framework/react/guide/selective-ssr#how-to-disable-ssr-of-the-root-route)
```
import * as React from 'react'

import {
  HeadContent,
  Outlet,
  Scripts,
  createRootRoute,
} from '@tanstack/react-router'

export const Route = createRootRoute({
  shellComponent: RootShell,
  component: RootComponent,
  errorComponent: () => <div>Error</div>,
  notFoundComponent: () => <div>Not found</div>,
  ssr: false, // or `defaultSsr: false` on the router
})

function RootShell({ children }: { children: React.ReactNode }) {
  return (
    <html>
      <head>
        <HeadContent />
      </head>
      <body>
        {children}
        <Scripts />
      </body>
    </html>
  )
}

function RootComponent() {
  return (
    <div>
      <h1>This component will be rendered on the client</h1>
      <Outlet />
    </div>
  )
}
```

# SEO
## What TanStack Start Provides [#](https://tanstack.com/start/v0/docs/framework/react/guide/seo#what-tanstack-start-provides)
- **Server-Side Rendering (SSR)** - Ensures crawlers receive fully rendered HTML

## Static Prerendering [#](https://tanstack.com/start/v0/docs/framework/react/guide/seo#static-prerendering)
```
import { defineConfig } from 'vite'
import { tanstackStart } from '@tanstack/react-start/plugin/vite'

export default defineConfig({
  plugins: [\
    tanstackStart({\
      prerender: {\
        enabled: true,\
        crawlLinks: true,\
      },\
    }),\
  ],
})
```

