## **Comparing TanStack Start’s Selective SSR to other frameworks**
### React Router
```typescript
// react-router.config.ts
import type { Config } from "@react-router/dev/config";

export default {
  // Server-side render by default, to enable SPA mode set this to `false`
  ssr: true,
  appDirectory: "src",
} satisfies Config;
```

# SSR with TanStack Start
## [1. Configure Vite](https://nitro.build/examples/vite-ssr-tss-react#_1-configure-vite)
```js
import { defineConfig } from "vite";
import { nitro } from "nitro/vite";
import { tanstackStart } from "@tanstack/react-start/plugin/vite";
import viteReact from "@vitejs/plugin-react";
import tailwindcss from "@tailwindcss/vite";

export default defineConfig({
  plugins: [tanstackStart(), viteReact(), tailwindcss(), nitro()],
  resolve: { tsconfigPaths: true },
  environments: {
    ssr: { build: { rollupOptions: { input: "./server.ts" } } },
  },
});
```

